from lib import *
S = SS('g29')
steps = [
    step("一次 cgo 调用的成本(7 轮取中位数):Go 函数 goAdd(1, 2)(//go:noinline)1.97 ns/op;C.c_add(1, 2)(一个只做加法的 C 函数)21.22 ns/op,约 10.8 倍;C.CString + C.c_strlen + C.free 74.73 ns/op,AllocsPerRun 是 0(C.CString 分配的是 C 堆,Go 的分配计数看不到);把 4096 字节的 Go 切片直接传给 C 求和(C.c_sum,不拷贝)72.03 ns/op,而同样的 Go 循环要 1266.25 ns/op。所以每次跨边界约 20 ns,批量交给 C 处理才划算。", t=tl(S(1)), done=lidx(S(1), 'goAdd', 'C.c_add'), mark=lidx(S(1), 'C.CString', 'C.c_sum', 'Go 循环对 4096'), b=bars([['Go goAdd', 1.97, '1.97'], ['C.c_add', 21.22, '21.22'], ['CString+strlen+free', 74.73, '74.73'], ['C.c_sum(4096 字节)', 72.03, '72.03'], ['Go 循环 4096 字节', 1266.25, '1266']], 1266.25, done=[0, 3], mark=[1, 2, 4]), kv=KV([['Go 函数调用', '1.97 ns'], ['cgo 调用(空函数)', '21.22 ns,约 10.8 倍'], ['C.c_sum 对 4096 字节', '72.03 ns(Go 循环 1266.25 ns)'], ['C.CString 的分配', '在 C 堆上,AllocsPerRun 为 0']], ['cgo 调用(空函数)'])),
    step("cgo 做了什么:go tool cgo -objdir gen main.go 生成 _cgo_2.o、_cgo_export.c、_cgo_export.h、_cgo_gotypes.go、_cgo_main.c、main.cgo1.go、main.cgo2.c。_cgo_gotypes.go 里 C.c_add 对应的 Go 包装 _Cfunc_c_add(p0, p1 _Ctype_int) 只做一件事:调用 _cgo_runtime_cgocall(函数指针, 参数地址),再用 _Cgo_use 保证参数在调用期间活着。", t=tl(S(2)), done=lidx(S(2), '生成的文件'), mark=lidx(S(2), '_cgo_runtime_cgocall', '_Cgo_use(p0)'), kv=KV([['生成的 Go 文件', 'main.cgo1.go、_cgo_gotypes.go'], ['生成的 C 文件', 'main.cgo2.c、_cgo_export.c、_cgo_main.c'], ['C.c_add 的包装', '_Cfunc_c_add → _cgo_runtime_cgocall(函数指针, 参数地址)']], ['C.c_add 的包装'])),
    step("阻塞在 C 里的 goroutine 占住一个线程:100 个 goroutine 各睡 300 ms。time.Sleep 版本:线程创建数 7 → 8(增加 1),总耗时 301 ms;C.usleep 版本:线程创建数 7 → 105(增加 98),总耗时 307 ms。", t=tl(S(3)), done=lidx(S(3), 'time.Sleep'), mark=lidx(S(3), 'C.usleep'), b=bars([['time.Sleep:新增线程', 1, '+1'], ['C.usleep:新增线程', 98, '+98']], 98, done=[0], mark=[1]), kv=KV([['100 个 goroutine 睡眠(Go)', '线程 7 → 8'], ['100 个 goroutine 阻塞在 C 里', '线程 7 → 105'], ['耗时', '都约 300 ms,但线程数差 98 个']], ['100 个 goroutine 阻塞在 C 里'])),
    step("限制:CGO_ENABLED=0 构建含 import \"C\" 的包:package lab: build constraints exclude all Go files;从 macOS 开着 CGO_ENABLED=1 交叉编译到 linux/amd64:runtime/cgo 的汇编被 macOS 的 clang 拒绝(gcc_amd64.S:27:8: error: unknown token in expression);把含 Go 指针的结构体指针传给 C(cgocheck 默认开启):panic runtime error: argument of cgo function has Go pointer to unpinned Go pointer。", t=tl(S(4)), mark=lidx(S(4), 'build constraints exclude all Go files', 'gcc_amd64.S', 'unpinned Go pointer'), kv=KV([['CGO_ENABLED=0', '含 import \"C\" 的包被排除:build constraints exclude all Go files'], ['macOS → linux/amd64 开启 cgo', '没有交叉的 C 工具链:clang 编译 runtime/cgo 失败'], ['传含 Go 指针的结构体给 C', 'panic:Go pointer to unpinned Go pointer']], ['CGO_ENABLED=0'])),
]
A = mkartg('g29', 29, 'Go,cgo,C,性能,线程,真实验证,动画演示',
    '在 Go 1.27.1(arm64 macOS,系统 clang)上量 cgo 的成本:一次空的 C 函数调用 21.22 ns(Go 调用 1.97 ns,约 10.8 倍);批量处理才划算(C 对 4096 字节求和 72.03 ns,Go 循环 1266.25 ns);go tool cgo 生成的包装只是调用 runtime.cgocall;100 个 goroutine 阻塞在 C 里会多创建 98 个线程(Go 的 time.Sleep 只多 1 个);CGO_ENABLED=0、交叉编译与 Go 指针传递规则的限制。',
    'cgo 让 Go 调用 C 库,但每次跨边界都有固定成本,还会改变调度与构建方式。这篇量出这个成本,看 cgo 工具生成了什么代码,验证阻塞在 C 里的 goroutine 为什么会占用线程,最后列出构建与指针规则上的限制。',
    [('21.22 ns', '一次 cgo 调用的耗时,Go 函数调用是 1.97 ns'), ('+98 个线程', '100 个 goroutine 阻塞在 C 里时多创建的线程数(time.Sleep 只多 1 个)'), ('72 ns vs 1266 ns', '对 4096 字节求和:一次 C 调用与 Go 循环')],
    [('一次调用的成本', '<p>cgo 调用要从 Go 的栈切到 C 能用的栈、通知调度器这个 goroutine 进入了 C、调用结束再切回来,所以一个只做加法的 C 函数也要约 21 ns。这是固定成本,和 C 函数本身干多少活无关:所以把大块数据一次交给 C(传 Go 切片的指针,不拷贝)才划算,逐个元素调用 C 反而更慢。这里的 C 求和比 Go 循环快得多,我猜有一部分是 clang 的优化(比如向量化),没有去看汇编确认。</p>'),
     ('生成了什么', '<p><code>go tool cgo</code> 把 <code>import "C"</code> 的文件拆成 Go 与 C 两部分,生成的 <code>_Cfunc_c_add</code> 很薄:调用 <code>runtime.cgocall</code>,参数打包成一个结构。<code>_Cgo_use</code> 防止参数在调用之前被回收。我没有读 <code>runtime.cgocall</code> 的实现,上面“切栈、通知调度器”是对它的名字与行为的概括,不是验证过的细节。</p>'),
     ('线程', '<p>实验的结果很直接:100 个 goroutine 阻塞在 <code>usleep</code> 里,线程数从 7 涨到 105;同样的 100 个 <code>time.Sleep</code> 只多一个线程。阻塞在 C 里的 goroutine 无法被调度器挂起复用线程,所以并发的阻塞 C 调用有多少就占多少线程。线程太多时要用信号量限制并发。</p>'),
     ('构建与指针规则', '<p><code>CGO_ENABLED=0</code> 时含 <code>import "C"</code> 的包整个被排除;在 macOS 上交叉编译到 Linux 时开着 cgo 会失败,因为需要目标平台的 C 工具链(这里是 clang 不认识 Linux 的汇编)。传给 C 的 Go 内存如果里面还含 Go 指针,运行时检查会 panic——需要先用 <code>runtime.Pinner</code> 固定,或者改成不含 Go 指针的数据结构(本文没有试 Pinner)。</p>')],
    steps,
    [ENV_G + '。系统 clang 21.0.0(Apple clang);cgo 用默认设置(CGO_ENABLED=1);基准测试每个变体 7 轮取中位数;线程数来自 runtime/pprof 的 threadcreate 计数(创建过的线程,不是当前线程);生成的文件来自 go tool cgo -objdir',
     '没有验证:runtime.cgocall 的内部实现、C 调用 Go 回调(//export)的成本、runtime.Pinner 的用法、Linux 上的数字与交叉工具链(zig cc 等)的做法、GODEBUG=cgocheck=0 的行为、cgo 对构建时间与二进制大小的影响'],
    'cgo 调用的开销')
